// CRM demo data: the ONE file that holds every invented value in the app.
// Names, IDs, dates, vitals, diagnoses, notes and file names are all made up;
// no row refers to a real person, clinic or company. Screens read from here and
// nowhere else, so edit this file to change what the app shows.
//
// "Today" is fixed (TODAY, NOW) rather than read from the clock, so the server
// and the browser always render the same page.

export type Urgency = 1 | 2 | 3 | 4
export type VisitStatus = 'waiting' | 'with-doctor' | 'done'
export type AttachmentKind = 'lab' | 'xray' | 'ecg' | 'ultrasound' | 'referral' | 'cert' | 'photo' | 'consent' | 'vaccine'

export type Doctor = { id: string; name: string; specialty: string; room: string }
export type Patient = { id: string; name: string; sex: 'F' | 'M'; born: number; allergy: string; conditions: string[] }
/** One clinic visit: the triage result taken on arrival plus the consultation record. */
export type Visit = {
  id: string
  patient: string
  /** ISO date, e.g. 2026-10-07. */
  date: string
  /** Arrival time, 24-hour HH:MM. */
  time: string
  doctor: string
  urgency: Urgency
  complaint: string
  /** Degrees Celsius. */
  temp: number
  /** Systolic/diastolic, mmHg. */
  bp: string
  /** Beats per minute. */
  hr: number
  /** Oxygen saturation, percent. */
  spo2: number
  /** Pain score, 0-10. */
  pain: number
  nurse: string
  status: VisitStatus
  /** Empty until the doctor has seen the patient. */
  diagnosis: string
  notes: string
}
export type Attachment = { id: string; visit: string; kind: AttachmentKind; name: string; kb: number }

/** The clinic's current day and time. */
export const TODAY = '2026-10-07'
export const NOW = '14:20'

export const URGENCY_LEVELS: { level: Urgency; code: string; label: string; target: string }[] = [
  { level: 1, code: 'P1', label: 'Critical', target: 'See immediately' },
  { level: 2, code: 'P2', label: 'Urgent', target: 'See within 15 min' },
  { level: 3, code: 'P3', label: 'Standard', target: 'See within 30 min' },
  { level: 4, code: 'P4', label: 'Routine', target: 'See within 60 min' },
]

export const VISIT_STATUSES: { value: VisitStatus; label: string }[] = [
  { value: 'waiting', label: 'Waiting' },
  { value: 'with-doctor', label: 'With doctor' },
  { value: 'done', label: 'Seen' },
]

